// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper that always reverts on calls to transferFrom
        Reverter reverter = new Reverter();
        bool ok = false;
        try c.transfer(from, address(reverter), _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // The reference C must either revert or return false if the sub-call fails
        // Since the helper reverts on transferFrom, the reference C must revert or return false
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
